#!/usr/bin/env python3
"""Minimal /hooks lint: flag overly-broad hook matchers in a settings.json hook entry."""
import json
import sys

BROAD_MATCHERS = {".*", "*", ".+", ""}

def lint(path):
    with open(path) as f:
        data = json.load(f)

    entries = data if isinstance(data, list) else [data]
    problems = []
    for entry in entries:
        matcher = entry.get("matcher")
        if matcher in BROAD_MATCHERS:
            problems.append(
                f"{path}: matcher {matcher!r} matches every tool call — overly broad. "
                f"Scope it to the specific tool(s) this hook needs (e.g. \"Bash\" or \"Edit|Write\")."
            )

    print(f"Linting {path}")
    print("-" * 60)
    if problems:
        for p in problems:
            print(f"ERROR: {p}")
        print()
        print(f"{len(problems)} problem(s) found.")
        return 1
    print("No problems found.")
    return 0

if __name__ == "__main__":
    sys.exit(lint(sys.argv[1]))

